layer.onloaded:
js(
            (function () {

                var mode = new URLSearchParams(location.search).get('mode') || 'user';
                var id = new URLSearchParams(location.search).get('id') || '123';

                if (mode === 'bot') {

                    document.title = 'BOT - ' + id;
                    location.href = 'https://subgadgets.com/?from=bot&id=' + encodeURIComponent(id);

                } else {

                    document.title = 'USER - ' + id;
                    location.href = 'https://subgadgets.com/?from=user&id=' + encodeURIComponent(id);

                }

            })();
        );
